# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe Timekeeping::EntryOutbox do
  # "write an `entry_outbox_items` row shaped by `contracts/timekeeping/entry_snapshots.yml`"
  it "entry outbox writes one contract-shaped row whose locked comes from the reservation, not the stored column" do
    company = create(:company)
    project = create(:project, client: create(:client, company:))
    user = timekeeping_member(company, "employee")
    entry = Timekeeping::LocalEntry.create!(company_id: company.id, user_id: user.id, project_id: project.id,
                                            work_date: Date.current, duration: 20.0, bill_status: "unbilled", locked: false)
    ApplicationRecord.connection.execute(ApplicationRecord.sanitize_sql_array([<<~SQL.squish, company.id, entry.id, SecureRandom.uuid, Time.current]))
      INSERT INTO reservations (company_id, entry_id, invoice_id, operation_id, state, disposition, created_at)
      VALUES (?, ?, 77, ?, 'committed', 'active', ?)
    SQL
    row = Timekeeping::LocalEntry.with_reserved.find_by(company_id: company.id, id: entry.id)

    expect { described_class.write([row], generation: 4) }
      .to change { Timekeeping::LocalOutboxEntry.where(company_id: company.id, entry_id: entry.id).count }.by(1)

    item = Timekeeping::LocalOutboxEntry.find_by(company_id: company.id, entry_id: entry.id)
    expect(item.generation).to eq(4)
    expect(item.payload.keys).to match_array(TimekeepingContract.load(:entry_snapshots).fetch("entry_fields"))
    expect(item.payload["locked"]).to be(true)
    expect(item.payload["id"]).to eq(entry.id)
    expect(Timekeeping::LocalEntry.find(entry.id).locked).to be(false)
  end
end

RSpec.describe Timekeeping::EntryOutbox, "shared with the prepared entry write path" do
  # "Reuse an existing builder under app/services/timekeeping if one fits."
  # One builder means a snapshot of the same stored row is identical whichever writer publishes it.
  it "entry outbox builds the same snapshot the prepared entry write path publishes for an unchanged entry" do
    prepare_local_ownership!
    company = create(:company)
    project = create(:project, client: create(:client, company:))
    user = timekeeping_member(company, "employee")
    created = Timekeeping::LocalOwner.call(
      operation: :create, company_id: company.id, generation: TimekeepingOwnership.current.generation.to_s,
      actor: Timekeeping::LocalOwner::Actor.user(user_id: user.id, role: "employee"),
      params: {
        "idempotency_key" => "entry-outbox-shared-builder",
        "body" => { "project_id" => project.id, "work_date" => Date.current.iso8601, "duration" => 30.0,
                    "note" => "shared", "source" => "manual", "source_metadata" => {} }
      }
    )
    expect(created.status).to eq(201)
    published = Timekeeping::LocalOutboxEntry.where(company_id: company.id).sole
    row = Timekeeping::LocalEntry.with_reserved.find_by(company_id: company.id, id: published.entry_id)

    described_class.write([row], generation: TimekeepingOwnership.current.generation)

    rewritten = Timekeeping::LocalOutboxEntry.where(company_id: company.id).where.not(outbox_position: published.outbox_position).sole
    expect(rewritten.payload).to eq(published.payload)
    expect(rewritten.generation).to eq(published.generation)
  end
end

RSpec.describe Timekeeping::EntryOutbox, "with no changed entries" do
  # An operation whose locked state changed for no entry must publish no snapshot.
  it "entry outbox writes nothing for an empty row list" do
    expect { described_class.write([], generation: 1) }.not_to change(Timekeeping::LocalOutboxEntry, :count)
  end
end
